"use strict";(globalThis.webpackChunkdoqumentation=globalThis.webpackChunkdoqumentation||[]).push([[9632],{74946(a,n,i){i.r(n),i.d(n,{assets:()=>u,contentTitle:()=>s,default:()=>p,frontMatter:()=>o,metadata:()=>g,toc:()=>l});const g=JSON.parse('{"id":"learning/courses/quantum-computing-in-practice/introduction","title":"Panimula","description":"Isang libreng kurso ng IBM sa utility-scale quantum computing na nagtatampok ng mga makatotohanang use case at pinakamahusay na mga kagawian","source":"@site/i18n/tl/docusaurus-plugin-content-docs/current/learning/courses/quantum-computing-in-practice/introduction.mdx","sourceDirName":"learning/courses/quantum-computing-in-practice","slug":"/learning/courses/quantum-computing-in-practice/introduction","permalink":"/learning/courses/quantum-computing-in-practice/introduction","draft":false,"unlisted":false,"editUrl":"https://github.com/JanLahmann/doQumentation/tree/main/docs/learning/courses/quantum-computing-in-practice/introduction.mdx","tags":[],"version":"current","frontMatter":{"title":"Panimula","sidebar_label":"Panimula","description":"Isang libreng kurso ng IBM sa utility-scale quantum computing na nagtatampok ng mga makatotohanang use case at pinakamahusay na mga kagawian","notebook_path":"learning/courses/quantum-computing-in-practice/introduction.ipynb"},"sidebar":"tutorialsSidebar","previous":{"title":"Pangkalahatang-ideya","permalink":"/learning/courses/quantum-computing-in-practice/"},"next":{"title":"Pagpapatakbo ng mga quantum circuit","permalink":"/learning/courses/quantum-computing-in-practice/running-quantum-circuits"}}');var t=i(74848),m=i(28453);const o={title:"Panimula",sidebar_label:"Panimula",description:"Isang libreng kurso ng IBM sa utility-scale quantum computing na nagtatampok ng mga makatotohanang use case at pinakamahusay na mga kagawian",notebook_path:"learning/courses/quantum-computing-in-practice/introduction.ipynb"},s="Panimula ng kurso {#course-introduction}",u={},l=[{value:"Tungkol sa kursong ito",id:"about-this-course",level:2},{value:"Quantum utility",id:"quantum-utility",level:3},{value:"Pag-simulate ng Kalikasan",id:"simulating-nature",level:3},{value:"Pokus sa mas malalaking quantum processor",id:"a-focus-on-larger-quantum-processors",level:3},{value:"Audience at mga layunin ng kurso",id:"audience-and-course-goals",level:3},{value:"Ang kwento ng computation",id:"the-story-of-computation",level:2},{value:"Mga computing device mula pa sa sinaunang panahon",id:"computing-devices-since-ancient-times",level:3},{value:"Mga koneksyon sa pisikal na mundo",id:"connections-to-the-physical-world",level:3},{value:"Moore&#39;s law",id:"moores-law",level:3},{value:"Quantum computing",id:"quantum-computing",level:2},{value:"Quantum mechanics at computation",id:"quantum-mechanics-and-computation",level:3},{value:"Quantum computing sa teorya",id:"quantum-computing-in-theory",level:3},{value:"Quantum computing sa praktis",id:"quantum-computing-in-practice",level:3},{value:"Mga potensyal na aplikasyon",id:"potential-applications",level:3},{value:"Estado ng teknolohiya",id:"state-of-the-technology",level:3},{value:"Konklusyon",id:"conclusion",level:2}];function e(a){const n={a:"a",em:"em",h1:"h1",h2:"h2",h3:"h3",header:"header",li:"li",p:"p",strong:"strong",ul:"ul",...(0,m.R)(),...a.components},{IBMVideo:i}=n;return i||function(a,n){throw new Error("Expected "+(n?"component":"object")+" `"+a+"` to be defined: you likely forgot to import, pass, or provide it.")}("IBMVideo",!0),(0,t.jsxs)(t.Fragment,{children:["\n",(0,t.jsx)(n.header,{children:(0,t.jsx)(n.h1,{id:"course-introduction",children:"Panimula ng kurso"})}),"\n",(0,t.jsxs)(n.p,{children:["Bago magsimula, pakikumpleto ang maikling ",(0,t.jsx)(n.a,{href:"https://your.feedback.ibm.com/jfe/form/SV_6PadhMQiGWsxXTM",children:"pre-course survey"})," na ito, na mahalaga para matulungang mapabuti ang aming mga nilalaman at karanasan ng gumagamit."]}),"\n",(0,t.jsxs)(n.p,{children:["I-click sa ibaba para marinig ang panimula ng kurso mula kay Olivia Lanes, o buksan ang video sa hiwalay na window sa ",(0,t.jsx)(n.a,{href:"https://youtube.com/watch?v=sVRpKhCfKRI",children:"YouTube."})]}),"\n",(0,t.jsx)(i,{id:"134063425",title:"In this video, Olivia Lanes gives an overview of practical quantum computing in the utility era. She covers intended audience and some background on subjects like Moore's law and theoretical foundations of quantum computing."}),"\n",(0,t.jsx)(n.h2,{id:"about-this-course",children:"Tungkol sa kursong ito"}),"\n",(0,t.jsxs)(n.p,{children:["Maligayang pagdating sa ",(0,t.jsx)(n.em,{children:"Quantum Computing in Practice"})," \u2014 isang kurso na nakatuon sa mga quantum computer ngayon at kung paano gamitin ang mga ito nang buong-buo.\nSinasaklaw nito ang mga makatotohanang potensyal na use case para sa quantum computing pati na rin ang pinakamahusay na mga kagawian para sa pagpapatakbo at pag-eeksperimento sa mga quantum processor na may 100 o higit pang qubit."]}),"\n",(0,t.jsx)(n.h3,{id:"quantum-utility",children:"Quantum utility"}),"\n",(0,t.jsxs)(n.p,{children:["Kapana-panabik na panahon ito para sa quantum computing.\nPagkatapos ng maraming taon ng teoretikal at eksperimental na pananaliksik at pagpapaunlad, papalapit na ang mga quantum computer sa puntong maaari na silang makipagkompetensya sa mga klasikal na computer at ipakita ang ",(0,t.jsx)(n.em,{children:"utility"}),"."]}),"\n",(0,t.jsxs)(n.p,{children:["Hindi pareho ang utility at ",(0,t.jsx)(n.em,{children:"quantum advantage"}),", na tumutukoy sa mga quantum computer na ",(0,t.jsx)(n.em,{children:"humihigit"})," sa mga klasikal na computer para sa mga makabuluhang gawain.\nAng mga klasikal na computer ay may kahanga-hangang kapangyarihan at kakayahang umangkop, at ang katotohanan ay ang mga quantum computer ay hindi pa talaga kaya pang talunin ang mga ito.\nNakita natin ang mga dekada ng mga pagsulong sa klasikal na computation \u2014 hindi lang sa computing hardware kundi pati na rin sa mga algorithm para sa mga klasikal na computer \u2014 at malinaw nating masasabing ang teknolohiya ng electronic digital computing ay radikal na nagbago ng ating mundo."]}),"\n",(0,t.jsxs)(n.p,{children:["Ang quantum computing naman ay nasa ibang yugto ng pag-unlad.\nAng quantum computing ay naglalagay ng matinding kahilingan sa ating kontrol ng mga quantum mechanical system at tinutulak ang mga hangganan ng teknolohiya ngayon \u2014 at hindi natin makatwirang inaasahan na mahahawakan natin ang bagong teknolohiyang ito at matatalo ang klasikal na computing kaagad-agad.\nNgunit nakakita na tayo ng mga palatandaan na nagmumungkahi na nagsisimula nang maging mapagkumpetensya ang mga quantum computer sa mga klasikal na paraan ng computing para sa mga piling gawain, na isang natural na hakbang sa teknolohikal na ebolusyon ng quantum computing na kilala bilang ",(0,t.jsx)(n.em,{children:"quantum utility"}),"."]}),"\n",(0,t.jsx)(n.p,{children:"Habang sumusulong ang teknolohiya at nagde-develop ng mga bagong pamamaraan para sa quantum computing, makatwirang inaasahan natin na ang mga kalamangan nito ay magiging lalong kapansin-pansin \u2014 ngunit magtatagal ito.\nHabang nangyayari ito, malamang na makakita tayo ng magkasalungat na interaksyon sa klasikal na computing:\nisasagawa ang mga demonstrasyon ng quantum computing at sasagot ang klasikal na computing, kukuha ng susunod na hakbang ang quantum computing, at uulit ang pattern.\nAt isang araw, kapag hindi na matutugmaan ng klasikal ang performance ng quantum computer, maghihipotesis tayo na nakita natin ang quantum advantage \u2014 pero kahit noon, hindi pa tayo makatitiyak!\nAng pagpapatunay ng mga resulta ng imposibilidad para sa mga klasikal na computer ay isang imposibleng mahirap na problema ayon sa ating kaalaman."}),"\n",(0,t.jsx)(n.h3,{id:"simulating-nature",children:"Pag-simulate ng Kalikasan"}),"\n",(0,t.jsx)(n.p,{children:"Ang mga klasikal na simulator \u2014 ibig sabihin, mga computer program na tumatakbo sa mga klasikal na computer na nagsi-simulate ng mga pisikal na sistema \u2014 ay maaaring gumawa ng mga hula tungkol sa mga quantum mechanical na sistema.\nNgunit ang mga klasikal na simulator ay hindi quantum at hindi direktang makakatulad ng mga quantum system.\nSa halip, gumagamit sila ng mga matematikal na kalkulasyon para mapalapit sa quantum na pag-uugali.\nHabang lumalaki ang mga sistema na sino-simulate, ang overhead na kailangan para gawin ito ay dramatikong tumataas, na naglalagay ng mga limitasyon sa kung aling mga quantum system ang maaaring i-simulate nang klasikal, gaano katagal ang mga simulation, at ang katumpakan ng mga resulta."}),"\n",(0,t.jsx)(n.p,{children:"Ang mga quantum computer naman ay makakapagtulad ng mga quantum system nang mas direkta \u2014 at bilang resulta, ang overhead na kailangan nila ay mas mahusay na nag-scale habang lumalaki ang sistema.\nIto, sa katunayan, ang ideya ni Richard Feynman noong 1980s na unang nagpasigla ng pananaliksik sa potensyal ng mga quantum computer.\nMarami pa tayong sasabihin tungkol dito sa ibang pagkakataon!"}),"\n",(0,t.jsx)(n.p,{children:"Naglathala ang mga mananaliksik ng IBM\xae ng papel noong 2023 na nagpakita, sa unang pagkakataon, na ang isang quantum computer ay makakakompetensya sa mga pinakabagong klasikal na pamamaraan para sa pag-simulate ng isang partikular na pisikal na modelo.\nAng mga resulta nito ay maaari pa ring matugmaan ng mga advanced na pamamaraan sa mga klasikal na computer \u2014 ngunit nalampasan nito ang mga brute-force na algorithm,\nat nag-aalok din ito ng bagong data point na kung saan maaaring ikumpara ang iba't ibang paraan ng simulation (na hindi eksakto at hindi lahat ay nagkakasundo sa kanilang mga hula)."}),"\n",(0,t.jsx)(n.h3,{id:"a-focus-on-larger-quantum-processors",children:"Pokus sa mas malalaking quantum processor"}),"\n",(0,t.jsx)(n.p,{children:"Ang mga dating gumagamit ng IBM quantum hardware ay maaaring nakapansin na ang mga mas maliliit na processor na dating ginawa naming available sa publiko ay na-offline na, na nagbibigay-daan para sa mga mas malalaking processor (na may 100+ qubit).\nAng mga mas maliliit na processor na iyon ay madaling ma-simulate nang klasikal.\nKaya, kahit kinatawan nila ang mga publicly accessible na hakbang sa isang sumusulong na teknolohiya, hindi nila kailanman maipapakita ang quantum utility: anumang magagawa sa kanila ay ganoon din kadaling magagawa sa pamamagitan ng klasikal na simulation."}),"\n",(0,t.jsxs)(n.p,{children:["Sa paligid ng 100 qubit, gayunpaman, hindi na ito ang kaso; ang mga quantum processor ng ganitong sukat ay hindi na maaaring i-simulate nang klasikal.\nIto ay kumakatawan sa isang uri ng phase-transition, sa isang bagong panahon ng teknolohiya ng quantum computing kung saan umiiral ang ",(0,t.jsx)(n.em,{children:"potensyal"})," para sa paghihigit sa klasikal na computation.\nIto ang piniling ipokus ng IBM \u2014 ang maghanap ng quantum computational na kapangyarihan at maabot ang isang magiging quantum advantage."]}),"\n",(0,t.jsx)(n.p,{children:"Hinihikayat namin ang aming mga gumagamit na gamitin ang mga bagong device na ito nang buong-buo, mag-eksperimento sa mga ito at itulak ang kanilang mga limitasyon, at dalhin ang mga araling natutunan sa susunod na henerasyon ng mga quantum processor na kasalukuyang pinagpapaunlad.\nAng layunin ng kursong ito ay paganahin kang gawin ito!"}),"\n",(0,t.jsx)(n.h3,{id:"audience-and-course-goals",children:"Audience at mga layunin ng kurso"}),"\n",(0,t.jsx)(n.p,{children:"Ang kursong ito ay para sa sinumang naglalayong mag-develop ng mga bagong aplikasyon para sa mga quantum computer, gustong palawakin ang kanilang kasalukuyang trabaho sa quantum computing, o matuto kung paano gamitin ang mga quantum processor sa loob ng kanilang workflow.\nKasama rito hindi lang ang mga pisiko at computer scientist, kundi pati na rin ang mga inhinyero, chemist, materials scientist, at sinumang may interes sa pag-aaral ng quantum computing hardware."}),"\n",(0,t.jsx)(n.p,{children:"Ang kurso ay hands-on at nakatuon sa praktikal na paggamit ng mga quantum computer.\nAng mga sumusunod na paksa at kasanayan ay kabilang sa mga saklaw nito:"}),"\n",(0,t.jsxs)(n.ul,{children:["\n",(0,t.jsx)(n.li,{children:"Pagpapatakbo ng mga utility-scale job sa mga quantum processor sa pamamagitan ng Qiskit Runtime"}),"\n",(0,t.jsx)(n.li,{children:"Paggamit ng mga teknik ng error mitigation para mapabuti ang mga resulta ng hardware"}),"\n",(0,t.jsx)(n.li,{children:"Mga potensyal na lugar ng aplikasyon para sa mga near-term quantum computer"}),"\n"]}),"\n",(0,t.jsxs)(n.p,{children:["Hindi sinasaklaw ng kursong ito ang panimulang teorya ng quantum computing, at ipinapalagay ang pangunahing pamilyaridad sa mga qubit at quantum circuit.\nAng kursong ",(0,t.jsx)(n.em,{children:"Basics of quantum information"})," sa platform na ito ay sinasaklaw ang materyal na ito, at inirerekomenda muna para sa mga bago sa quantum computing."]}),"\n",(0,t.jsx)(n.h2,{id:"the-story-of-computation",children:"Ang kwento ng computation"}),"\n",(0,t.jsxs)(n.p,{children:["Ang quantum computing ay isang kapana-panabik na bagong teknolohiya sa maagang yugto ng pag-unlad \u2014 ngunit isa lang itong kabanata sa isang kwentong bumabalik sa libu-libong taon.\nIto ang kwento ng ",(0,t.jsx)(n.em,{children:"computation"})," at ng maraming-facet na koneksyon nito sa ",(0,t.jsx)(n.em,{children:"pisikal na mundo"}),"."]}),"\n",(0,t.jsx)(n.h3,{id:"computing-devices-since-ancient-times",children:"Mga computing device mula pa sa sinaunang panahon"}),"\n",(0,t.jsxs)(n.p,{children:["Mula pa sa sinaunang panahon, kailangan natin bilang mga tao na magsagawa ng mga ",(0,t.jsx)(n.em,{children:"computation"})," \u2014 o, sa ibang salita, mag-proseso ng impormasyon ayon sa ilang mga panuntunan at limitasyon \u2014 para paganahin ang komunikasyon, konstruksyon, komersyo, agham, at iba pang aspeto ng ating buhay.\nLumingon tayo sa pisikal na mundo para sa tulong, at sa pamamagitan ng matalinong mga natuklasan, nakagawa tayo ng mga device para tulungan tayong mag-compute."]}),"\n",(0,t.jsxs)(n.p,{children:["Noong matagal na panahon, ang mga device na gawa sa kahoy, buto, at mga knotted na lubid ay nag-iimbak ng impormasyon at nagpapadali ng mga kalkulasyon.\nAng mga mekanikal na device na gawa sa mga lever, gear, at iba pang makinarya ay umunlad mula sa mga maagang astronomical clock, sa mga calculator, sa mga sopistikadong computing device tulad ng mga differential analyzer na naglutas ng mga equation gamit ang mga gulong at umiikot na disk.\nKahit ang teknolohiya ng pagsulat ay may mahalagang papel sa kwentong ito sa pamamagitan ng pagpapahintulot sa ",(0,t.jsx)(n.em,{children:"mga tao"})," na magsagawa ng mga computation na hindi nila magagawa kung hindi."]}),"\n",(0,t.jsx)(n.p,{children:"Kapag iniisip natin ang mga computer ngayon, may tendensya tayong mag-isip tungkol sa mga electronic digital computer.\nNgunit ito ay medyo kamakailang teknolohiya: ang mga electronic digital computer ay unang itinayo noong 1940s.\n(Sa kaibahan, ang Sumerian abacus ay pinaniniwalaan na naimimbento sa pagitan ng 2700 at 2300 BC.)\nAng teknolohiya ay dramatikong sumusulong mula noon at ang mga computer ay laganap na ngayon.\nMakikita sila sa mga tahanan, lugar ng trabaho, at ang mga sasakyan na nagdadala sa atin sa pagitan nila, at marami sa atin ang nagdadala sa kanila saan man tayo pumunta."}),"\n",(0,t.jsxs)(n.p,{children:["Mayroon din tayong mga ",(0,t.jsx)(n.em,{children:"supercomputer"}),", na malalaking koleksyon ng mga makapangyarihang klasikal na processor na konektado nang parallel.\nIsa sila sa mga pinakamahusay na tool na itinayo ng sangkatauhan para sa paglutas ng mga mahirap na problema, at patuloy na sumusulong ang kanilang kapangyarihan at pagiging maaasahan.\nNgunit pa rin, mayroong mga mahahalagang computational na problema na kahit ang mga behemoth na ito ay hindi kailanman makakalutas, dahil sa likas na computational na kahirapan ng mga problemang ito."]}),"\n",(0,t.jsx)(n.h3,{id:"connections-to-the-physical-world",children:"Mga koneksyon sa pisikal na mundo"}),"\n",(0,t.jsxs)(n.p,{children:["Maraming gamit ang mga computer.\nAng isang mahalagang gamit ng mga computer ay ang ",(0,t.jsx)(n.em,{children:"matuto"})," tungkol sa pisikal na mundo at mas maunawaan ang mga pattern nito.\nAng mga makasaysayang gamit sa kategoryang ito ay kinabibilangan ng hula ng mga eklipso at alon, pag-unawa sa paggalaw ng mga astronomical na katawan, at (sa medyo mas kamakailang panahon) pag-model ng mga pagsabog.\nNgayon, halos walang physics lab sa buong mundo na walang computer."]}),"\n",(0,t.jsxs)(n.p,{children:["Sa mas malawak na pananaw, ang physics at computation ay laging magkasama.\nHindi maaaring umiral ang computation sa vacuum: ang impormasyon ay nangangailangan ng medium, at para mag-compute kailangan nating gamitin ang pisikal na mundo sa ilang paraan.\nSi Rolf Landauer, isang computer scientist (at IBMer), ay nakilala noong matagal na panahon na ang impormasyon ay pisikal, umiiral lamang sa pamamagitan ng pisikal na representasyon.\nAng ",(0,t.jsx)(n.em,{children:"Landauer's principle"})," ay nagtatag ng koneksyon sa pagitan ng impormasyon at mga batas ng thermodynamics, ngunit sa katunayan maraming koneksyon."]}),"\n",(0,t.jsx)(n.p,{children:"Ang pag-unawa sa pisikal na mundo ay layunin ng physics bilang disiplina, ngunit sa katunayan ito ay dalawang-daan.\nSa pamamagitan ng ating pag-unawa sa pisikal na mundo, nagagawa nating gamitin ang mga bagong teknolohiya para tulungan tayong mag-compute, at sa pamamagitan nila patuloy tayong natututo tungkol sa pisikal na mundo \u2014 mahalagang hinihila ang physics at computational na teknolohiya pataas."}),"\n",(0,t.jsx)(n.h3,{id:"moores-law",children:"Moore's law"}),"\n",(0,t.jsx)(n.p,{children:"Ang Moore's law ay isang obserbasyon na ang pinakamataas na bilang ng mga transistor sa isang integrated circuit ay doble nang halos bawat 2 taon.\nSa nakalipas na 5 dekada o higit pa, hindi lang natin naobserbahan ang trend na ito kundi naabot din natin ang mga reward nito.\nSa mas maraming transistor sa isang chip, maaari tayong magsagawa ng mas kumplikadong mga computation at mas mabilis nating magagawa ang mga ito.\nIto ang dahilan kung bakit nagiging mas at mas makapangyarihan ang mga computer sa paglipas ng panahon."}),"\n",(0,t.jsx)(n.p,{children:'Gayunpaman, ang "batas" ni Moore ay, sa pangangailangan, malapit na sa katapusan.\nHindi nagkakasundo ang mga eksperto sa kung kailan mangyayari ito, at ang ilan ay nagtaltalan na nangyari na ito.\nNgunit alam natin nang tiyak na dapat itong matapos sa huli dahil may teoretikal na limitasyon sa miniaturisasyon ng mga bahagi ng computing.\nHindi natin magagawang gawing mas maliit ang isang transistor kaysa sa isang atom!\nKahit mukhang pinalabis iyon, ito ang pader na papalapit tayo.'}),"\n",(0,t.jsx)(n.p,{children:'Ang solusyon ay hindi ang sumuko at sabihing, "Ganyan na lang iyon sa pinakamahusay."\nIto ay laban sa kalikasan ng tao.\nSa halip, kailangan nating lumingon sa pisikal na mundo para sa mga bagong computational na tool, at dito pumapasok ang quantum computing.'}),"\n",(0,t.jsx)(n.h2,{id:"quantum-computing",children:"Quantum computing"}),"\n",(0,t.jsx)(n.h3,{id:"quantum-mechanics-and-computation",children:"Quantum mechanics at computation"}),"\n",(0,t.jsx)(n.p,{children:"Natuklasan ang quantum mechanics noong maagang ika-20 siglo, at mahalaga na ang papel nito sa computation.\nSa katunayan, ang ating pag-unawa sa quantum mechanics ay, sa bahagi, nagpahintulot sa mga computer ngayon.\nKung wala ang quantum mechanics, halimbawa, mahirap isipin na naimimbento ang solid state hard drive."}),"\n",(0,t.jsx)(n.h3,{id:"quantum-computing-in-theory",children:"Quantum computing sa teorya"}),"\n",(0,t.jsx)(n.p,{children:"Nang unang iminungkahi ni Richard Feynman ang konsepto ng isang quantum computer noong 1982, ang kanyang pokus ay sa pag-simulate ng mga quantum mechanical na sistema.\nAng mga kalkulasyon na kailangan para gawin ito ay mukhang masyadong mahirap para sa mga ordinaryong computer \u2014 ngunit baka, gamit ang isang computer na gumagana ayon sa quantum mechanical na paglalarawan ng mundo, ang mga sistema ay maaaring direktang itulad."}),"\n",(0,t.jsx)(n.p,{children:"Ngayon ito ay isa sa mga pinaka-promising na landas para sa quantum computing.\nAyon sa ating pinakamahusay na pag-unawa, ang Kalikasan ay hindi klasikal \u2014 ito ay quantum.\nKaya, ang mga quantum computer ay maaaring maging mahalagang tool para sa pag-unawa nito.\nAng mga klasikal na computer naman ay makakaapproximate lamang ng aktwal na nangyayari sa Kalikasan, at sa ilang mga kaso ang mga\napproximation na iyon ay napaka-limitado."}),"\n",(0,t.jsx)(n.p,{children:"Isang paraan para isipin ito ay sa pamamagitan ng analogy sa mga wind tunnel.\nAng fluid dynamics ay kilala-kilalang mahirap i-simulate at hulaan nang matematikal.\nHalimbawa, masyadong mahal at hindi praktikal na i-simulate ang isang kotse na nagmamaneho sa hangin, kaya sa halip ang mga gumagawa ng kotse ay nagtatayo talaga ng mga tunnel na may humihipas na hangin at nagpapatakbo ng mga kotse sa mga ito para subukan ang kanilang performance.\nIbig sabihin, lumilikha sila ng hangin sa halip na i-simulate ito.\nAng pagtatayo ng quantum computer para pag-aralan ang pisikal na mundo ay parang pagtatayo ng wind tunnel para pag-aralan kung paano nakakaapekto ang hangin sa mga kotse.\nAng mga quantum computer ay direktang makakatulad ng mga batas ng Kalikasan sa molecular na antas dahil kumikilos sila ayon sa mga batas na iyon,\nibig sabihin, tinutulad nila ang Kalikasan sa halip na i-simulate ito sa pamamagitan ng mga formula at kalkulasyon."}),"\n",(0,t.jsxs)(n.p,{children:["Sumunod ang iba sa mga ideya ni Feynman \u2014 at iniugnay nila ang mga ideyang ito sa isang teorya ng ",(0,t.jsx)(n.em,{children:"quantum information"})," na\ndati nang nasa proseso ng pag-unlad.\nIpinanganak ang larangan ng ",(0,t.jsx)(n.em,{children:"quantum information and computation"}),".\nMula noon ito ay naging isang mayamang, multidisciplinary na larangan ng pag-aaral, at maraming mga kalamangan ng quantum kumpara sa klasikal na impormasyon at computation ang natukoy sa malawak na iba't ibang ",(0,t.jsx)(n.em,{children:"teoretikal"})," na setting na kinabibilangan ng komunikasyon, computation, at cryptography."]}),"\n",(0,t.jsx)(n.h3,{id:"quantum-computing-in-practice",children:"Quantum computing sa praktis"}),"\n",(0,t.jsx)(n.p,{children:"Sa praktikal na termino, dalawang bagay ang kailangan para ilipat ang ganitong uri ng mga teoretikal na kalamangan sa mga tunay na kalamangan: ang mga device mismo at ang mga pamamaraan para ma-unlock ang kanilang potensyal."}),"\n",(0,t.jsx)(n.p,{children:"Hindi tulad ng mga klasikal na computer, walang quantum computer na naka-imbak sa bulsa ng sinuman.\nHanggang kamakailan lamang, kung gusto mong mag-eksperimento sa isang quantum computer, kailangan mong itayo at panatilihin ito mismo\n(karaniwang sa isang malungkot na basement lab sa isang unibersidad o pasilidad ng pananaliksik), at magkakaroon ka lang ng ilang, napaka-noisy na qubit.\nHindi na ito ang kaso.\nNoong 2016, inilagay ng IBM Quantum\xae ang unang quantum processor sa cloud.\nLimang qubit lang ang mayroon nito at medyo mataas na rate ng error, ngunit malayo na tayo mula noon.\nIbubuod natin ang kasalukuyang estado ng teknolohiya sa isang seksyon sa ibaba."}),"\n",(0,t.jsx)(n.p,{children:"Bukod sa pagtatayo ng mga quantum computer, kailangan din nating mag-develop ng mga pamamaraan para gamitin ang mga ito nang epektibo.\nHabang ang mga teoretikal na pagsulong sa mga quantum algorithm at protocol ay nagmumungkahi ng matibay na potensyal, ang hamon ng paghahanap ng mga praktikal na gamit para sa quantum computing ay nasa harap pa rin natin.\nAng mga quantum computer ngayon ay hindi pa kayang magsagawa ng mga fault-tolerant na computation na kailangan para ilipat ang mga kilalang teoretikal na kalamangan sa mga praktikal na kalamangan.\nNgunit lampas na sila sa kakayahan ng mga klasikal na computer simulation, at maaari tayong maghangad na i-leverage ang katotohanang ito para sa computational na kapangyarihan."}),"\n",(0,t.jsx)(n.p,{children:"Sa pamamagitan ng mga pagsulong na ito, mayroon tayong bagong tool para sa computation, at nasa atin ang pag-alamin kung ano ang magagawa natin sa kanya."}),"\n",(0,t.jsx)(n.h3,{id:"potential-applications",children:"Mga potensyal na aplikasyon"}),"\n",(0,t.jsx)(n.p,{children:"Hindi inaasahan na ang quantum computing ay magiging kapaki-pakinabang para sa pag-aaral kung paano gumaganap ang mga kotse sa hangin.\nNgunit may iba pang mga pisikal na proseso \u2014 tulad ng mga kasangkot sa disenyo ng mga baterya o sa ilang mga reaksiyon ng kemikal \u2014 kung saan ang kakayahan ng quantum computer na tularan ang Kalikasan ay maaaring humantong sa isang quantum advantage.\nSa mas malawak na pananaw, maraming mga problema na masyadong mahirap o mahal kahit para sa pinakabagong mga supercomputer, kabilang ang mga problema na lubos na may kaugnayan sa ating lipunan.\nAng quantum computing ay maaaring hindi mag-alok ng mga solusyon sa lahat ng ito, ngunit maaari itong mag-alok ng mga solusyon sa ilan."}),"\n",(0,t.jsx)(n.p,{children:"Ang sumusunod na tatlong lugar ng aplikasyon ay kumakatawan sa mga target sa lugar ng noisy quantum computing, bago ang implementasyon ng quantum error correction at fault-tolerance."}),"\n",(0,t.jsxs)(n.ul,{children:["\n",(0,t.jsx)(n.li,{children:"Optimization"}),"\n",(0,t.jsx)(n.li,{children:"Pag-simulate ng Kalikasan"}),"\n",(0,t.jsx)(n.li,{children:"Paghahanap ng estruktura sa data (kasama ang machine learning)"}),"\n"]}),"\n",(0,t.jsx)(n.p,{children:"Tatalakayin natin ang mga paksa na ito nang mas detalyado sa ibang pagkakataon sa kurso."}),"\n",(0,t.jsx)(n.h3,{id:"state-of-the-technology",children:"Estado ng teknolohiya"}),"\n",(0,t.jsx)(n.p,{children:"Ang pagtatayo ng mga quantum computer ay isang mahirap na teknolohikal na hamon, at walo lamang taon na lumipas mula nang maging available ang maliliit na quantum computer sa publiko.\nSa loob ng 8 taon na iyon, nakagawa na tayo ng pag-unlad sa maraming larangan."}),"\n",(0,t.jsxs)(n.p,{children:["Maraming IBM quantum processor ang accessible na ngayon sa pamamagitan ng cloud, lahat ng mga ito ay may higit sa 100 qubit.\nNgunit hindi lang ang sukat ng mga processor ang mahalaga \u2014 iyon ay isa lang sa metric na iniingatan natin.\nAng kalidad ng gate ay dramatiko ring bumuti, at nagpakilala rin tayo ng mga pamamaraan ng pagbabawas at pagpapagaan ng mga error na likas sa mga quantum system, kahit habang itinutulak natin ang paglikha ng mga fault-tolerant na sistema.\nTatlong pangunahing metric \u2014 ",(0,t.jsx)(n.em,{children:"scale"}),", ",(0,t.jsx)(n.em,{children:"quality"}),", at ",(0,t.jsx)(n.em,{children:"speed"})," \u2014 ay mahalaga sa pagsubaybay ng pagpapabuti ng performance."]}),"\n",(0,t.jsxs)(n.ul,{children:["\n",(0,t.jsxs)(n.li,{children:["\n",(0,t.jsxs)(n.p,{children:[(0,t.jsx)(n.strong,{children:"Sukat."})," Mas maraming qubit ay mas maganda, ngunit kung at saan lamang ang pagtaas ng bilang ay hindi nagdedegrada ng performance\n(na maaaring maging kaso). Sa katunayan, gusto natin ng mas maraming, mataas na kalidad na qubit na hindi nakikialam sa isa't isa\nsa pamamagitan ng crosstalk kapag hindi natin gusto iyon. Ang paraan ng pagkonekta ng mga qubit sa isa't isa ay mahalaga rin, at\nang pag-alam kung paano pinakamahusay na gawin ito ay isang hamon para sa mga superconducting qubit circuit."]}),"\n"]}),"\n",(0,t.jsxs)(n.li,{children:["\n",(0,t.jsxs)(n.p,{children:[(0,t.jsx)(n.strong,{children:"Kalidad."})," Ang isa pang mahalagang metric na aming sinusubaybayan, para masubaybayan ang pagpapabuti ng performance sa paglipas ng panahon, ay ang 2-qubit gate fidelity.\nAng mga gate na tumatakbo sa mga solong qubit ay hindi kasinit ng prone sa mga error tulad ng mga 2-qubit gate, na siyang mas malaking alalahanin.\n(Ang mga 2-qubit gate ay mahalaga rin dahil sila ang responsable sa paglikha ng entanglement sa pagitan ng mga qubit, na\nhypothesized na isa sa mga phenomenon ng physics na nagbibigay sa quantum computing ng kapangyarihan nito.)"]}),"\n"]}),"\n",(0,t.jsxs)(n.li,{children:["\n",(0,t.jsxs)(n.p,{children:[(0,t.jsx)(n.strong,{children:"Bilis."})," Huli ay bilis at kahusayan. Sa madaling salita, ang oras na ginugugol sa pagpapatakbo ng isang programa (kasama ang parehong quantum at\nklasikal na bahagi) ay dapat na maikli hangga't maaari."]}),"\n"]}),"\n"]}),"\n",(0,t.jsx)(n.h2,{id:"conclusion",children:"Konklusyon"}),"\n",(0,t.jsx)(n.p,{children:"Kapana-panabik na panahon talaga ang trabaho sa larangan ng quantum computing: sa unang pagkakataon sa kasaysayan, maaari na tayong magsimulang tuklasin ang isang rehiyon ng computing na lampas sa klasikal na computation."}),"\n",(0,t.jsx)(n.p,{children:"Isang beses na kilala si T.J. Watson na hinulaan ang world market para sa ilang computer lamang.\nMaaari tayong tumawa ngayon sa gaano siya kalayo sa katotohanan \u2014 ngunit habang ginagawa natin ito, kailangan nating kilalanin na mayroon tayong benepisyo ng hindsight.\nAt dapat din nating kilalanin na, bilang mga tao, mayroon tayong pangkalahatang tendensya na labis na maliitin ang potensyal ng mga teknolohiya sa hinaharap.\nNgayon na ang ating turn at gumaganap tayo bilang mga maagang pioneer ng quantum computing, dapat nating tandaan ito."}),"\n",(0,t.jsx)(n.p,{children:"Ang quantum computing ay madalas na ipinagkaiba sa klasikal na computing, bilang isang bagay na naiiba mula rito at nakikipagkompetensya dito.\nNgunit mula sa mas malawak na pananaw, maaari nating makita ang quantum computing bilang isa pang kabanata lamang sa isang mahabang kwento.\nIto ang ating kalikasan bilang mga tao na hanapin ang mga bagong paraan upang mag-compute at gamitin ang kapangyarihan na ibinibigay sa atin ng natural na mundo para gawin ito.\nGinagawa na natin ito sa loob ng mga siglo.\nAng quantum computing ay nag-aalok sa atin ng bagong tool sa pagsisikap na ito at nasa atin ang tuklasin kung paano natin magagamit ang kapangyarihang inaalok nito sa atin."})]})}function p(a={}){const{wrapper:n}={...(0,m.R)(),...a.components};return n?(0,t.jsx)(n,{...a,children:(0,t.jsx)(e,{...a})}):e(a)}},28453(a,n,i){i.d(n,{R:()=>o,x:()=>s});var g=i(96540);const t={},m=g.createContext(t);function o(a){const n=g.useContext(m);return g.useMemo(function(){return"function"==typeof a?a(n):{...n,...a}},[n,a])}function s(a){let n;return n=a.disableParentContext?"function"==typeof a.components?a.components(t):a.components||t:o(a.components),g.createElement(m.Provider,{value:n},a.children)}}}]);